func majorityElement(nums []int) int {
	counts := map[int]int{}
	for _, num := range nums {
		counts[num]++
	}
	majority, maxCount := 0, 0
	for k, v := range counts {
		if v > maxCount {
			majority, maxCount = k, v
		}
	}
	return majority
}

