func majorityElement(nums []int) int {
	majorityCount := len(nums) / 2
	for {
		candidate := nums[rand.Intn(len(nums))]
		count := 0
		for _, elem := range nums {
			if elem == candidate {
				count++
			}
		}
		if count > majorityCount {
			return candidate
		}
	}
}

func majorityElement(nums []int) int {
	var majorityElementRec func(lo, hi int) int
	majorityElementRec = func(lo, hi int) int {
		// base case; the only element in an array of size 1 is the majority
		// element.
		if lo == hi {
			return nums[lo]
		}
		// recurse on left and right halves of this slice.
		mid := (hi-lo)/2 + lo
		left := majorityElementRec(lo, mid)
		right := majorityElementRec(mid+1, hi)
		// if the two halves agree on the majority element, return it.
		if left == right {
			return left
		}
		// otherwise, count each element and return the "winner".
		leftCount := 0
		for i := lo; i <= hi; i++ {
			if nums[i] == left {
				leftCount++
			}
		}
		rightCount := 0
		for i := lo; i <= hi; i++ {
			if nums[i] == right {
				rightCount++
			}
		}
		if leftCount > rightCount {
			return left
		}
		return right
	}
	return majorityElementRec(0, len(nums)-1)
}

func majorityElement(nums []int) int {
	count, candidate := 0, 0
	for _, num := range nums {
		if count == 0 {
			candidate = num
		}
		if num == candidate {
			count++
		} else {
			count--
		}
	}
	return candidate
}
